# ── Write all files ────────────────────────────────────────────────────────────
updates = [
    ('ingredients_a_f.json', new_af),
    ('ingredients_g_l.json', new_gl),
    ('ingredients_m_r.json', new_mr),
    ('ingredients_s_z.json', new_sz),
]

grand_total_added = 0
for filename, new_data in updates:
    path = os.path.join(base, filename)
    with open(path, encoding='utf-8') as f:
        existing = json.load(f)

    existing_ids = {item['id'] for item in existing}
    to_add = [item for item in new_data if item['id'] not in existing_ids]
    combined = existing + to_add

    with open(path, 'w', encoding='utf-8') as f:
        json.dump(combined, f, ensure_ascii=False, indent=2)

    grand_total_added += len(to_add)
    print(filename + ': ' + str(len(existing)) + ' -> ' + str(len(combined)) + ' (+' + str(len(to_add)) + ' new)')

print('\nGrand total added: ' + str(grand_total_added))
